import React, { useState, useEffect } from 'react';
import { 
  StyleSheet, Text, View, TextInput, TouchableOpacity, 
  SafeAreaView, ScrollView, Alert, Image, FlatList 
} from 'react-native';
import { StatusBar } from 'expo-status-bar';

// --- CHARTE GRAPHIQUE (NSP Style) ---
const COLORS = {
  bg: '#121212',        // Fond très sombre
  card: '#1E1E1E',      // Cartes gris foncé
  primary: '#E63946',   // Rouge Sport
  text: '#FFFFFF',      // Texte blanc
  subText: '#AAAAAA',   // Texte gris
  success: '#2A9D8F',   // Vert pour "Tout va bien"
  warning: '#E9C46A',   // Jaune pour "Attention"
  input: '#2C2C2C'
};

export default function App() {
  // Gestion de la navigation simple pour le prototype
  // Ecrans possibles: 'auth', 'addCar', 'dashboard', 'addInvoice'
  const [currentScreen, setCurrentScreen] = useState('auth');

  const [user, setUser] = useState(null);
  const [car, setCar] = useState(null); // Données de la voiture
  const [invoices, setInvoices] = useState([]); // Liste des factures

  // Fonction pour simuler l'IA qui analyse l'état
  const getAIStatus = () => {
    if (invoices.length === 0) return { status: 'warning', msg: "Aucun historique. Ajoutez une facture pour activer le suivi IA." };
    return { status: 'success', msg: "IA : Analyse terminée. Prochaine révision dans 4500 km." };
  };

  // Rendu conditionnel des écrans
  const renderScreen = () => {
    switch (currentScreen) {
      case 'auth':
        return <AuthScreen onLogin={(u) => { setUser(u); setCurrentScreen('addCar'); }} />;
      case 'addCar':
        return <AddCarScreen onSave={(c) => { setCar(c); setCurrentScreen('dashboard'); }} />;
      case 'dashboard':
        return <DashboardScreen 
                 user={user} 
                 car={car} 
                 invoices={invoices}
                 aiStatus={getAIStatus()}
                 onAddInvoice={() => setCurrentScreen('addInvoice')}
                 onLogout={() => { setUser(null); setCar(null); setCurrentScreen('auth'); }}
               />;
      case 'addInvoice':
        return <AddInvoiceScreen 
                 onSave={(inv) => { setInvoices([inv, ...invoices]); setCurrentScreen('dashboard'); }}
                 onCancel={() => setCurrentScreen('dashboard')}
               />;
      default:
        return <AuthScreen />;
    }
  };

  return (
    <SafeAreaView style={styles.container}>
      <StatusBar style="light" />
      {renderScreen()}
    </SafeAreaView>
  );
}

// --- 1. ECRAN AUTHENTIFICATION ---
function AuthScreen({ onLogin }) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [nom, setNom] = useState('');

  return (
    <View style={styles.centerContainer}>
      <Text style={styles.logoTitle}>NSP AUTO</Text>
      <Text style={styles.subtitle}>Votre garage virtuel personnel</Text>

      <View style={styles.form}>
        <TextInput placeholder="Nom & Prénom" placeholderTextColor={COLORS.subText} style={styles.input} onChangeText={setNom} />
        <TextInput placeholder="Email" placeholderTextColor={COLORS.subText} style={styles.input} onChangeText={setEmail} />
        <TextInput placeholder="Mot de passe" placeholderTextColor={COLORS.subText} secureTextEntry style={styles.input} onChangeText={setPassword} />

        <TouchableOpacity style={styles.btnPrimary} onPress={() => onLogin({ name: nom || 'Conducteur' })}>
          <Text style={styles.btnText}>DEMARRER L'EXPERIENCE 🚗</Text>
        </TouchableOpacity>
      </View>
    </View>
  );
}

// --- 2. ECRAN CREATION VOITURE (ONBOARDING) ---
function AddCarScreen({ onSave }) {
  const [plate, setPlate] = useState('');

  return (
    <ScrollView contentContainerStyle={styles.scrollContainer}>
      <Text style={styles.headerTitle}>Ajout Véhicule</Text>
      <Text style={styles.textBody}>Scannez ou entrez votre véhicule pour commencer le suivi.</Text>

      {/* Zone Photos 4 angles */}
      <Text style={styles.sectionTitle}>Photos du véhicule (4 angles)</Text>
      <View style={styles.photoGrid}>
        {[1, 2, 3, 4].map((i) => (
          <TouchableOpacity key={i} style={styles.photoPlaceholder}>
            <Text style={{fontSize: 24}}>📷</Text>
            <Text style={{color: COLORS.subText, fontSize: 10}}>Angle {i}</Text>
          </TouchableOpacity>
        ))}
      </View>

      <Text style={styles.sectionTitle}>Immatriculation</Text>
      <View style={styles.plateContainer}>
        <View style={styles.plateBlueLeft}><Text style={{color:'white', fontSize:10}}>F</Text></View>
        <TextInput 
          style={styles.plateInput} 
          placeholder="AB-123-CD" 
          placeholderTextColor="#999"
          autoCapitalize="characters"
          onChangeText={setPlate}
        />
        <View style={styles.plateBlueRight} />
      </View>

      <TouchableOpacity style={styles.btnPrimary} onPress={() => onSave({ plate: plate || 'AB-123-CD' })}>
        <Text style={styles.btnText}>VALIDER MON VEHICULE</Text>
      </TouchableOpacity>
    </ScrollView>
  );
}

// --- 3. DASHBOARD (GARAGE VIRTUEL) ---
function DashboardScreen({ user, car, invoices, aiStatus, onAddInvoice, onLogout }) {
  return (
    <ScrollView style={styles.container}>
      {/* Header */}
      <View style={styles.dashHeader}>
        <View>
          <Text style={styles.welcome}>Garage de {user.name}</Text>
          <View style={styles.plateTag}>
            <Text style={{fontWeight:'bold'}}>{car.plate}</Text>
          </View>
        </View>
        <TouchableOpacity onPress={onLogout}>
          <Text style={{color: COLORS.primary}}>Sortir</Text>
        </TouchableOpacity>
      </View>

      {/* Alertes IA */}
      <View style={[styles.aiCard, { borderColor: aiStatus.status === 'success' ? COLORS.success : COLORS.warning }]}>
        <View style={{flexDirection:'row', alignItems:'center', marginBottom: 5}}>
          <Text style={{fontSize:18, marginRight:10}}>✨</Text>
          <Text style={{color: COLORS.text, fontWeight:'bold'}}>Assistant IA</Text>
        </View>
        <Text style={{color: COLORS.subText}}>{aiStatus.msg}</Text>
      </View>

      {/* Rappels Intelligents */}
      <Text style={styles.sectionTitle}>Prochaines Échéances</Text>
      <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{marginBottom: 20}}>
        <ReminderCard title="Vidange" date="Dans 3 mois" color={COLORS.success} icon="🛢️" />
        <ReminderCard title="Contrôle Tech." date="02/2026" color={COLORS.success} icon="🔍" />
        <ReminderCard title="Pression Pneus" date="Vérifier" color={COLORS.warning} icon="⚠️" />
      </ScrollView>

      {/* Boite à gants numérique */}
      <View style={styles.rowBetween}>
        <Text style={styles.sectionTitle}>Boîte à Gants (Factures)</Text>
        <TouchableOpacity onPress={onAddInvoice}>
          <Text style={{color: COLORS.primary, fontWeight:'bold'}}>+ AJOUTER</Text>
        </TouchableOpacity>
      </View>

      {invoices.length === 0 ? (
        <View style={styles.emptyState}>
          <Text style={{fontSize:30, marginBottom:10}}>📂</Text>
          <Text style={{color: COLORS.subText, textAlign:'center'}}>
            Votre boîte à gants est vide.{'\n'}Ajoutez une facture pour que l'IA analyse votre entretien.
          </Text>
        </View>
      ) : (
        invoices.map((inv, index) => (
          <View key={index} style={styles.invoiceItem}>
            <View style={styles.invoiceIcon}><Text>🧾</Text></View>
            <View style={{flex:1}}>
              <Text style={{color: COLORS.text, fontWeight:'bold'}}>{inv.title}</Text>
              <Text style={{color: COLORS.subText, fontSize: 12}}>{inv.date} • {inv.km} km</Text>
            </View>
            <Text style={{color: COLORS.success, fontWeight:'bold'}}>{inv.price} €</Text>
          </View>
        ))
      )}

      <View style={{height: 50}} />
    </ScrollView>
  );
}

// --- 4. ECRAN AJOUT FACTURE ---
function AddInvoiceScreen({ onSave, onCancel }) {
  const [type, setType] = useState('');
  const [km, setKm] = useState('');
  const [price, setPrice] = useState('');

  return (
    <View style={styles.scrollContainer}>
      <Text style={styles.headerTitle}>Scanner Facture</Text>

      <TouchableOpacity style={styles.scanBox}>
        <Text style={{fontSize: 40}}>📸</Text>
        <Text style={{color: COLORS.text, marginTop: 10}}>Prendre la facture en photo</Text>
        <Text style={{color: COLORS.subText, fontSize: 12}}>L'IA lira les détails automatiquement</Text>
      </TouchableOpacity>

      <Text style={styles.sectionTitle}>Détails (Correction manuelle)</Text>
      <TextInput placeholder="Type (ex: Vidange, Pneus)" placeholderTextColor={COLORS.subText} style={styles.input} onChangeText={setType} />
      <TextInput placeholder="Kilométrage actuel" placeholderTextColor={COLORS.subText} keyboardType='numeric' style={styles.input} onChangeText={setKm} />
      <TextInput placeholder="Montant (€)" placeholderTextColor={COLORS.subText} keyboardType='numeric' style={styles.input} onChangeText={setPrice} />

      <View style={{flexDirection: 'row', justifyContent:'space-between', marginTop: 20}}>
        <TouchableOpacity style={[styles.btnPrimary, {backgroundColor: '#333', flex: 0.4}]} onPress={onCancel}>
          <Text style={styles.btnText}>ANNULER</Text>
        </TouchableOpacity>
        <TouchableOpacity style={[styles.btnPrimary, {flex: 0.5}]} onPress={() => onSave({ title: type || 'Entretien divers', km: km || '0', price: price || '0', date: new Date().toLocaleDateString() })}>
          <Text style={styles.btnText}>SAUVEGARDER</Text>
        </TouchableOpacity>
      </View>
    </View>
  );
}

// Composant Carte Rappel
const ReminderCard = ({ title, date, color, icon }) => (
  <View style={[styles.reminderCard, { borderLeftColor: color }]}>
    <Text style={{fontSize: 20}}>{icon}</Text>
    <View style={{marginLeft: 10}}>
      <Text style={{color: COLORS.subText, fontSize: 12}}>{title}</Text>
      <Text style={{color: COLORS.text, fontWeight: 'bold'}}>{date}</Text>
    </View>
  </View>
);

// --- STYLES ---
const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: COLORS.bg },
  scrollContainer: { padding: 20, flex: 1, backgroundColor: COLORS.bg },
  centerContainer: { flex: 1, backgroundColor: COLORS.bg, justifyContent: 'center', padding: 20 },

  // Textes
  logoTitle: { fontSize: 40, fontWeight: '900', color: COLORS.primary, textAlign: 'center', letterSpacing: 2 },
  subtitle: { fontSize: 16, color: COLORS.subText, textAlign: 'center', marginBottom: 40 },
  headerTitle: { fontSize: 28, fontWeight: 'bold', color: COLORS.text, marginBottom: 10, marginTop: 30 },
  sectionTitle: { fontSize: 18, fontWeight: 'bold', color: COLORS.text, marginTop: 25, marginBottom: 15 },
  textBody: { color: COLORS.subText, fontSize: 14, marginBottom: 20 },
  welcome: { color: COLORS.subText, fontSize: 14 },

  // Formulaires
  input: { backgroundColor: COLORS.input, color: COLORS.text, padding: 15, borderRadius: 8, marginBottom: 15, borderWidth: 1, borderColor: '#333' },
  btnPrimary: { backgroundColor: COLORS.primary, padding: 18, borderRadius: 8, alignItems: 'center' },
  btnText: { color: 'white', fontWeight: 'bold', fontSize: 16 },

  // Plaques
  plateContainer: { flexDirection: 'row', height: 50, marginBottom: 20 },
  plateBlueLeft: { backgroundColor: '#003399', width: 30, borderTopLeftRadius: 5, borderBottomLeftRadius: 5, alignItems:'center', justifyContent:'center' },
  plateBlueRight: { backgroundColor: '#003399', width: 30, borderTopRightRadius: 5, borderBottomRightRadius: 5 },
  plateInput: { flex: 1, backgroundColor: 'white', color: 'black', fontSize: 20, fontWeight: 'bold', textAlign: 'center', padding: 5 },

  // Photos
  photoGrid: { flexDirection: 'row', justifyContent: 'space-between', flexWrap: 'wrap' },
  photoPlaceholder: { width: '48%', aspectRatio: 1.5, backgroundColor: COLORS.card, borderRadius: 10, alignItems: 'center', justifyContent: 'center', marginBottom: 10, borderStyle: 'dashed', borderWidth: 1, borderColor: '#444' },

