  invoiceIcon: { width: 40, height: 40, backgroundColor: '#333', borderRadius: 20, alignItems: 'center', justifyContent: 'center', marginRight: 15 },
  emptyState: { alignItems: 'center', padding: 40, opacity: 0.5 },

  scanBox: { height: 200, backgroundColor: COLORS.card, borderRadius: 15, alignItems: 'center', justifyContent: 'center', borderStyle: 'dashed', borderWidth: 2, borderColor: COLORS.primary, marginBottom: 20 }
