  grayCardUrl: string | null;
  photos: {
    front: string | null;
    back: string | null;
    left: string | null;
    right: string | null;
    engine: string | null;
    damages: string[];
  };
  initialState: {
    tires: 'good' | 'average' | 'bad';
    brakes: 'good' | 'average' | 'bad';
    body: 'good' | 'average' | 'bad';
    interior: 'good' | 'average' | 'bad';
    engine: 'good' | 'average' | 'bad';
  };
  // La mémoire technique du véhicule
  specs?: TechnicalSpecs;
  // Assurance
